type RawMenuItem = {
  section_id: string;
  section_title: string;
  name: string;
  price: string | null;
};

function buildMenuSections(items: RawMenuItem[]): MenuSection[] {
  const grouped = new Map<string, MenuSection>();
  for (const item of items) {
    if (!grouped.has(item.section_id)) {
      const meta = sectionMeta[item.section_id];
      grouped.set(item.section_id, {
        id: item.section_id,
        title: meta?.title ?? item.section_title,
        banner: meta?.banner ?? assets.hero,
        icon: meta?.icon ?? assets.hero,
        items: [],
      });
    }
    grouped.get(item.section_id)!.items.push({ name: item.name, price: item.price ?? "" });
  }
  return Array.from(grouped.values());
}

